public class SpringDynamics extends Dynamics {
    private float mDamping;
    private float mFriction;
    private float mStiffness;

    public void setFriction(float friction) {
        this.mFriction = friction;
    }

    public void setSpring(float stiffness, float dampingRatio) {
        this.mStiffness = stiffness;
        this.mDamping = 2.0f * dampingRatio * ((float) Math.sqrt(stiffness));
    }

    private float calculateAcceleration() {
        float distanceFromLimit = getDistanceToLimit();
        if (distanceFromLimit != 0.0f) {
            float acceleration = (this.mStiffness * distanceFromLimit) - (this.mDamping * this.mVelocity);
            return acceleration;
        }
        float acceleration2 = (-this.mFriction) * this.mVelocity;
        return acceleration2;
    }

    @Override // com.gasolin.android.metro.util.Dynamics
    protected void onUpdate(int dt) {
        float fdt = dt / 1000.0f;
        float a = calculateAcceleration();
        this.mPosition += (this.mVelocity * fdt) + (0.5f * a * fdt * fdt);
        this.mVelocity += a * fdt;
    }
}

